// Crusaders Mainframe — the peer link port (Mega Serial3 <-> ESP8266 Serial).
//
// WHY THIS EXISTS
// ---------------
// The two halves of the court box talk over a 9600 8N1 line-terminated link
// routed by the DIP block. The wiring cannot change, so neither can the baud:
// 9600 is 960 bytes/second, and a 40-byte frame occupies the link for ~42 ms.
// That is slow enough that "the buffer was full" is an ordinary Tuesday, not an
// exotic failure, which is why this port surfaces back-pressure instead of
// pretending writes always succeed.
//
// WHY write() IS BYTES AND writeLine() IS A FREE FUNCTION
// -------------------------------------------------------
// Framing (`!VERB,args*CC\n`, checksummed — see docs/specs/device-serial-
// protocol.md) belongs to lib/protocol, not to the HAL. A virtual writeLine()
// would push the terminator, the maximum line length and a line-assembly buffer
// down into every implementation, duplicated per target, below the level the
// host tests exercise.
//
// So the port stays a byte pipe with one extra question — writable() — and the
// line-oriented convenience is the free function at the bottom of this file,
// which needs no vtable slot and is shared by every implementation.
//
// WHY writable() EARNS ITS VTABLE SLOT
// ------------------------------------
// Without it there is no way to write a whole frame or none of it. Half a frame
// on the wire is worse than no frame: the peer fails its checksum, discards it,
// AND the tail bytes are then read as the start of the next frame, so one
// overrun corrupts two messages. writable() lets the caller decide to drop a
// frame deliberately, which is a recoverable event with a name (`!EVT,OVERRUN`).
//
// No Arduino headers. Compiles for AVR, Xtensa and the host test runner.

#ifndef CRUSADERS_HAL_TRANSPORT_H
#define CRUSADERS_HAL_TRANSPORT_H

#include <stddef.h>
#include <stdint.h>
#include <string.h>

namespace hal {

class ITransport {
public:
  virtual ~ITransport() = default;

  /// True while the link is usable. On the Mega side this is effectively always
  /// true (a UART has no carrier), but on the ESP side the peer can be absent,
  /// resetting or mid-OTA, and the simulator's TCP transport really does drop.
  virtual bool connected() = 0;

  /// Bytes write() will accept right now. Zero when disconnected.
  ///
  /// Advisory, not a promise: a driver may still accept fewer bytes than this.
  /// Callers must check write()'s return value regardless.
  virtual size_t writable() = 0;

  /// Queue up to `len` bytes; returns how many were accepted, which may be zero
  /// (full buffer, failed or disconnected link) or any value below `len`
  /// (partial write). Never blocks — a blocking write at 9600 baud would stall
  /// the relay auto-off timer for tens of milliseconds per frame.
  virtual size_t write(const uint8_t* data, size_t len) = 0;

  /// Pop one received byte. False when nothing is waiting; never blocks.
  virtual bool read(uint8_t& out) = 0;
};

/// Write `text` plus the '\n' terminator, all of it or none of it.
///
/// Returns false without writing anything when the link is down or writable()
/// says the whole line will not fit. The caller should then count an overrun
/// and drop the frame — retrying a truncated frame is not possible, because the
/// bytes already accepted cannot be un-written.
///
/// HONEST LIMIT: writable() is advisory. If a port promises room and then
/// under-accepts, this returns false with a fragment already on the wire. That
/// is unavoidable at this layer; the peer's checksum is what catches it, and
/// the recording fake can reproduce exactly this case so the handling above is
/// tested rather than assumed.
inline bool writeLine(ITransport& port, const char* text) {
  if (text == nullptr || !port.connected()) {
    return false;
  }
  const size_t len = strlen(text);
  if (port.writable() < len + 1U) {
    return false;
  }
  if (len > 0U && port.write(reinterpret_cast<const uint8_t*>(text), len) != len) {
    return false;
  }
  const uint8_t terminator = static_cast<uint8_t>('\n');
  return port.write(&terminator, 1U) == 1U;
}

} // namespace hal

#endif // CRUSADERS_HAL_TRANSPORT_H
